INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Beginne ich hier ohne den Wert zu definieren?', 2, '[{"text": "Nein", "correct": true, "because": "Wert definieren ist erster Schritt"}, {"text": "Ja", "correct": false, "because": "Fokus auf Wert zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Schritt mache ich zuerst in diesem Prozess?', 3, '[{"text": "Wert definieren", "correct": true, "because": "Kundennutzen festlegen"}, {"text": "MVP entwickeln", "correct": false, "because": "Folgt Wertdefinition"}, {"text": "Feedback sammeln", "correct": false, "because": "Später im Zyklus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phasen gehören zu diesem Ablauf?', 5, '[{"text": "Prozesse analysieren", "correct": true, "because": "Effizienz prüfen"}, {"text": "Verbesserungen umsetzen", "correct": true, "because": "Optimierung anwenden"}, {"text": "Einmalige Entwicklung", "correct": false, "because": "Iterativ nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) MVP wird früh entwickelt. b) Feedback ist unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Feedback essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich in diesem Ablauf?', 4, '[{"text": "Wert definieren", "correct": false, "because": "Kern des Ansatzes"}, {"text": "Feedback sammeln", "correct": false, "because": "Verbesserung treiben"}, {"text": "Überflüssige Features", "correct": true, "because": "Fokus auf Effizienz"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier ohne MVP arbeite?', 2, '[{"text": "Nein", "correct": true, "because": "MVP ist zentral"}, {"text": "Ja", "correct": false, "because": "Minimum Viable Product nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Phase wähle ich, um Effizienz zu prüfen?', 3, '[{"text": "Prozesse analysieren", "correct": true, "because": "Verschwendung erkennen"}, {"text": "Feedback sammeln", "correct": false, "because": "Rückmeldung einholen"}, {"text": "Wert definieren", "correct": false, "because": "Nutzen festlegen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte fördern schnelle Lieferung?', 5, '[{"text": "MVP entwickeln", "correct": true, "because": "Schnell nutzbar"}, {"text": "Verbesserungen umsetzen", "correct": true, "because": "Effizienz steigern"}, {"text": "Komplexe Features", "correct": false, "because": "Minimaler Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Wert steht im Mittelpunkt. b) Prozesse sind nebensächlich. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Prozesse werden analysiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "Wert definieren", "correct": false, "because": "Kernprinzip"}, {"text": "MVP entwickeln", "correct": false, "because": "Schnelle Lieferung"}, {"text": "Überflüssige Funktionen", "correct": true, "because": "Effizienz im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sammle ich hier nur einmal Feedback?', 2, '[{"text": "Nein", "correct": true, "because": "Iterativ gesammelt"}, {"text": "Ja", "correct": false, "because": "Fortlaufender Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente verbessern die Effizienz?', 4, '[{"text": "Prozesse analysieren", "correct": true, "because": "Verschwendung reduzieren"}, {"text": "Verbesserungen umsetzen", "correct": true, "because": "Optimierung anwenden"}, {"text": "Komplexe Entwicklung", "correct": false, "because": "Minimaler Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ich hier ohne Wert arbeite. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Wert definieren ist Basis"}, {"text": "Ja", "correct": false, "because": "Kundennutzen im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich zu Beginn?', 3, '[{"text": "Wert definieren", "correct": true, "because": "Kundennutzen klären"}, {"text": "MVP entwickeln", "correct": false, "because": "Folgt Wert"}, {"text": "Feedback überspringen", "correct": false, "because": "Rückmeldung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Feedback treibt Verbesserung. b) MVP ist unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "MVP essenziell"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile hat dieser Ablauf?', 5, '[{"text": "Schnelle Lieferung", "correct": true, "because": "MVP früh nutzbar"}, {"text": "Effizienz", "correct": true, "because": "Prozesse optimiert"}, {"text": "Überflüssige Features", "correct": false, "because": "Minimaler Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier weniger wichtig?', 3, '[{"text": "Wert definieren", "correct": false, "because": "Kern des Ansatzes"}, {"text": "Feedback sammeln", "correct": false, "because": "Verbesserung treiben"}, {"text": "Unnötige Komplexität", "correct": true, "because": "Effizienz im Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Feedback hier nebensächlich?', 3, '[{"text": "Nein", "correct": true, "because": "Treibt Verbesserungen"}, {"text": "Ja", "correct": false, "because": "Rückmeldung zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ich hier ohne Prozessanalyse arbeite?', 2, '[{"text": "Nein", "correct": true, "because": "Prozesse analysieren ist Schritt"}, {"text": "Ja", "correct": false, "because": "Effizienz prüfen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Schritt wähle ich nach dem MVP?', 4, '[{"text": "Feedback sammeln", "correct": true, "because": "Rückmeldung einholen"}, {"text": "Wert definieren", "correct": false, "because": "Schon geschehen"}, {"text": "Prozesse analysieren", "correct": false, "because": "Vor MVP"}]');
